+                            <AccessibleButton
+                                element="button"
+                                type="submit"
+                                kind="primary"
+                                disabled={!this.state.token}
+                                onClick={this.onSubmit}
+                            >
+                                {_t("Continue")}
+                            </AccessibleButton>
+                        )}
+                    </div>
+                </form>
+            </div>
+        );
+    }
+}
